#[rustfmt::skip]
fn string_coercion<A: IVm>() {
    check::<A>("number", (123f64).to_any().to_string().map(|v| v.to_any()), string_any("123"));
    check::<A>("negativeNumber", (-456f64).to_any().to_string().map(|v| v.to_any()), string_any("-456"));
    check::<A>("zero", (0f64).to_any().to_string().map(|v| v.to_any()), string_any("0"));
    check::<A>("negativeZero", (-0f64).to_any().to_string().map(|v| v.to_any()), string_any("0"));
    check::<A>("infinity", (f64::INFINITY).to_any().to_string().map(|v| v.to_any()), string_any("Infinity"));
    check::<A>("negativeInfinity", (f64::NEG_INFINITY).to_any().to_string().map(|v| v.to_any()), string_any("-Infinity"));
    check::<A>("nan", (f64::NAN).to_any().to_string().map(|v| v.to_any()), string_any("NaN"));
    check::<A>("booleanTrue", true.to_any().to_string().map(|v| v.to_any()), string_any("true"));
    check::<A>("booleanFalse", false.to_any().to_string().map(|v| v.to_any()), string_any("false"));
    check::<A>("null", Nullish::Null.to_any().to_string().map(|v| v.to_any()), string_any("null"));
    check::<A>("undefined", Nullish::Undefined.to_any().to_string().map(|v| v.to_any()), string_any("undefined"));
    check::<A>("string", string_any("already").to_string().map(|v| v.to_any()), string_any("already"));
    check::<A>("bigint", bigint_any(123).to_string().map(|v| v.to_any()), string_any("123"));
    check::<A>("negativeBigint", bigint_any(-456).to_string().map(|v| v.to_any()), string_any("-456"));
    check::<A>("emptyArray", Array::default().to_any().to_string().map(|v| v.to_any()), string_any(""));
    check::<A>("singletonArray", [(1f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any("1"));
    check::<A>("array", [(1f64).to_any(), (2f64).to_any(), (3f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any("1,2,3"));
    check::<A>("nestedArray", [(1f64).to_any(), [(2f64).to_any(), (3f64).to_any()].to_array().to_any(), (4f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any("1,2,3,4"));
    check::<A>("arrayWithNullish", [Nullish::Null.to_any(), Nullish::Undefined.to_any(), (1f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any(",,1"));
    check::<A>("emptyObject", Object::default().to_any().to_string().map(|v| v.to_any()), string_any("[object Object]"));
    check::<A>("object", [(string_key("a"), (1f64).to_any())].to_object().to_any().to_string().map(|v| v.to_any()), string_any("[object Object]"));
}

pub fn all<A: IVm>() {
    eq::<A>();
    unary_plus::<A>();
    neg::<A>();
    mul::<A>();
    div::<A>();
    pow::<A>();
    sub::<A>();
    add::<A>();
    rem::<A>();
    string_coercion::<A>();
}
